1	package com.example.starter.water;
2	
3	import com.example.starter.water.WaterRepository.AllocationRow;
4	import com.example.starter.water.WaterRepository.CommandRow;
5	import com.example.starter.water.WaterRepository.CurtailmentRow;
6	import com.example.starter.water.WaterRepository.WindowRow;
7	import com.example.starter.water.dto.Dtos.AllocationResponse;
8	import com.example.starter.water.dto.Dtos.CapacityResponse;
9	import com.example.starter.water.dto.Dtos.CurtailmentResponse;
10	import com.example.starter.water.dto.Dtos.HistoryResponse;
11	import com.example.starter.water.dto.Dtos.WindowResponse;
12	import com.fasterxml.jackson.databind.ObjectMapper;
13	import org.springframework.dao.DuplicateKeyException;
14	import org.springframework.stereotype.Service;
15	import org.springframework.transaction.PlatformTransactionManager;
16	import org.springframework.transaction.support.TransactionTemplate;
17	
18	import java.math.BigDecimal;
19	import java.time.Instant;
20	import java.time.format.DateTimeParseException;
21	import java.util.List;
22	import java.util.function.Supplier;
23	import java.util.regex.Pattern;
24	
25	/**
26	 * 灌区配水业务服务。
27	 *
28	 * <p>幂等：每个写命令携带 commandKey，事务内先占位插入命令行再执行业务并写回响应；
29	 * 同键同参重放返回首次结果，同键改参返回 409。</p>
30	 *
31	 * <p>并发：批准申请与创建/取消限供在同一事务内先对窗口行 SELECT ... FOR UPDATE，
32	 * 按事务提交顺序生效，保证已批准总量永不超过最终可用总量。</p>
33	 */
34	@Service
35	public class WaterService {
36	
37	    static final String STATUS_REQUESTED = "REQUESTED";
38	    static final String STATUS_APPROVED = "APPROVED";
39	    static final String STATUS_CANCELLED = "CANCELLED";
40	
41	    private static final long NANOS_PER_SECOND = 1_000_000_000L;
42	    private static final Pattern AMOUNT_PATTERN = Pattern.compile("\\d{1,16}(\\.\\d{1,3})?");
43	    private static final Pattern KEY_PATTERN = Pattern.compile("[\\w.\\-:]{1,128}");
44	
45	    private final WaterRepository repository;
46	    private final TransactionTemplate tx;
47	    private final ObjectMapper objectMapper;
48	
49	    public WaterService(WaterRepository repository, PlatformTransactionManager transactionManager,
50	                        ObjectMapper objectMapper) {
51	        this.repository = repository;
52	        this.tx = new TransactionTemplate(transactionManager);
53	        this.objectMapper = objectMapper;
54	    }
55	
56	    // ------------------------------------------------------------------
57	    // 命令入口
58	    // ------------------------------------------------------------------
59	
60	    /** 创建供水窗口。 */
61	    public WindowResponse createWindow(String commandKey, String windowKey, String channelId,
62	                                       String startUtc, String endUtc, String plannedVolume) {
63	        requireKey("commandKey", commandKey);
64	        requireKey("windowKey", windowKey);
65	        requireKey("channelId", channelId);
66	        long startNanos = parseInstant("startUtc", startUtc);
67	        long endNanos = parseInstant("endUtc", endUtc);
68	        if (startNanos >= endNanos) {
69	            throw ApiException.badRequest("INVALID_ARGUMENT", "startUtc 必须早于 endUtc");
70	        }
71	        BigDecimal planned = parseAmount("plannedVolume", plannedVolume);
72	        String params = "WINDOW_CREATE|" + windowKey + "|" + channelId + "|" + startNanos + "|" + endNanos
73	                + "|" + planned.toPlainString();
74	        return runCommand("WINDOW_CREATE", commandKey, params, WindowResponse.class, () -> {
75	            if (repository.existsOverlappingWindow(channelId, startNanos, endNanos)) {
76	                throw ApiException.conflict("WINDOW_OVERLAP", "同一渠道存在时间重叠的供水窗口");
77	            }
78	            long id = repository.insertWindow(windowKey, channelId, startNanos, endNanos, planned, nowNanos());
79	            WindowRow row = repository.findWindowById(id);
80	            return toWindowResponse(row, null);
81	        });
82	    }
83	
84	    /** 提交配水申请，申请人为 actor。 */
85	    public AllocationResponse submitAllocation(String commandKey, String allocationKey, Long windowId,
86	                                               String userId, String amount, String actor) {
87	        requireKey("commandKey", commandKey);
88	        requireKey("allocationKey", allocationKey);
89	        requireKey("userId", userId);
90	        requireKey("X-Actor-Id", actor);
91	        if (windowId == null) {
92	            throw ApiException.badRequest("INVALID_ARGUMENT", "windowId 不能为空");
93	        }
94	        BigDecimal qty = parseAmount("amount", amount);
95	        String params = "ALLOCATION_SUBMIT|" + allocationKey + "|" + windowId + "|" + userId + "|"
96	                + qty.toPlainString() + "|" + actor;
97	        return runCommand("ALLOCATION_SUBMIT", commandKey, params, AllocationResponse.class, () -> {
98	            WindowRow window = repository.lockWindowById(windowId);
99	            if (window == null) {
100	                throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + windowId);
101	            }
102	            long id = repository.insertAllocation(allocationKey, windowId, userId, qty, actor, nowNanos());
103	            return toAllocationResponse(repository.findAllocationByKey(allocationKey));
104	        });
105	    }
106	
107	    /** 批准申请：加入本申请后已批准总量不得超过当前可用总量，否则 422。 */
108	    public AllocationResponse approveAllocation(String commandKey, String allocationKey) {
109	        requireKey("commandKey", commandKey);
110	        requireKey("allocationKey", allocationKey);
111	        String params = "ALLOCATION_APPROVE|" + allocationKey;
112	        return runCommand("ALLOCATION_APPROVE", commandKey, params, AllocationResponse.class, () -> {
113	            AllocationRow allocation = repository.findAllocationByKey(allocationKey);
114	            if (allocation == null) {
115	                throw ApiException.notFound("ALLOCATION_NOT_FOUND", "配水申请不存在: " + allocationKey);
116	            }
117	            WindowRow window = lockWindowOf(allocation);
118	            switch (allocation.status()) {
119	                case STATUS_CANCELLED ->
120	                        throw ApiException.conflict("ALLOCATION_CANCELLED", "已取消的申请不能批准");
121	                case STATUS_APPROVED ->
122	                        throw ApiException.conflict("ALLOCATION_ALREADY_APPROVED", "申请已批准，不能重复批准");
123	                default -> {
124	                }
125	            }
126	            BigDecimal available = availableTotal(window);
127	            BigDecimal approved = repository.sumApprovedAmount(window.id());
128	            if (approved.add(allocation.amount()).compareTo(available) > 0) {
129	                throw ApiException.quotaExceeded("批准后将超过当前可用总量 " + fmt(available));
130	            }
131	            repository.updateAllocationStatus(allocation.id(), STATUS_APPROVED, nowNanos());
132	            return toAllocationResponse(repository.findAllocationByKey(allocationKey));
133	        });
134	    }
135	
136	    /** 取消申请：仅申请人本人可取消 REQUESTED/APPROVED，取消不可恢复并立即释放水量。 */
137	    public AllocationResponse cancelAllocation(String commandKey, String allocationKey, String actor) {
138	        requireKey("commandKey", commandKey);
139	        requireKey("allocationKey", allocationKey);
140	        requireKey("X-Actor-Id", actor);
141	        String params = "ALLOCATION_CANCEL|" + allocationKey + "|" + actor;
142	        return runCommand("ALLOCATION_CANCEL", commandKey, params, AllocationResponse.class, () -> {
143	            AllocationRow allocation = repository.findAllocationByKey(allocationKey);
144	            if (allocation == null) {
145	                throw ApiException.notFound("ALLOCATION_NOT_FOUND", "配水申请不存在: " + allocationKey);
146	            }
147	            lockWindowOf(allocation);
148	            if (!allocation.requester().equals(actor)) {
149	                throw ApiException.conflict("NOT_OWNER", "只有申请人本人可以取消该申请");
150	            }
151	            if (STATUS_CANCELLED.equals(allocation.status())) {
152	                throw ApiException.conflict("ALLOCATION_ALREADY_CANCELLED", "申请已取消，不能重复取消");
153	            }
154	            repository.updateAllocationStatus(allocation.id(), STATUS_CANCELLED, nowNanos());
155	            return toAllocationResponse(repository.findAllocationByKey(allocationKey));
156	        });
157	    }
158	
159	    /** 创建限供：仅当当前已批准总量不超过拟定限供水量时允许。 */
160	    public CurtailmentResponse createCurtailment(String commandKey, long windowId, String volume) {
161	        requireKey("commandKey", commandKey);
162	        BigDecimal qty = parseAmount("volume", volume);
163	        String params = "CURTAILMENT_CREATE|" + windowId + "|" + qty.toPlainString();
164	        return runCommand("CURTAILMENT_CREATE", commandKey, params, CurtailmentResponse.class, () -> {
165	            WindowRow window = repository.lockWindowById(windowId);
166	            if (window == null) {
167	                throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + windowId);
168	            }
169	            if (qty.compareTo(window.plannedVolume()) > 0) {
170	                throw ApiException.badRequest("INVALID_ARGUMENT", "限供水量不能超过计划水量 " + fmt(window.plannedVolume()));
171	            }
172	            if (repository.findActiveCurtailment(windowId) != null) {
173	                throw ApiException.conflict("CURTAILMENT_EXISTS", "窗口已存在生效中的限供");
174	            }
175	            BigDecimal approved = repository.sumApprovedAmount(windowId);
176	            if (approved.compareTo(qty) > 0) {
177	                throw ApiException.conflict("CURTAILMENT_BELOW_APPROVED",
178	                        "当前已批准总量 " + fmt(approved) + " 超过拟定限供水量 " + fmt(qty));
179	            }
180	            long id = repository.insertCurtailment(windowId, qty, nowNanos());
181	            return toCurtailmentResponse(repository.findActiveCurtailment(windowId));
182	        });
183	    }
184	
185	    /** 取消当前生效限供，恢复计划水量。 */
186	    public CurtailmentResponse cancelCurtailment(String commandKey, long windowId) {
187	        requireKey("commandKey", commandKey);
188	        String params = "CURTAILMENT_CANCEL|" + windowId;
189	        return runCommand("CURTAILMENT_CANCEL", commandKey, params, CurtailmentResponse.class, () -> {
190	            WindowRow window = repository.lockWindowById(windowId);
191	            if (window == null) {
192	                throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + windowId);
193	            }
194	            CurtailmentRow active = repository.findActiveCurtailment(windowId);
195	            if (active == null) {
196	                throw ApiException.conflict("NO_ACTIVE_CURTAILMENT", "窗口没有生效中的限供");
197	            }
198	            repository.cancelCurtailment(active.id(), nowNanos());
199	            List<CurtailmentRow> all = repository.listCurtailments(windowId);
200	            return all.stream().filter(c -> c.id() == active.id()).findFirst()
201	                    .map(this::toCurtailmentResponse).orElseThrow();
202	        });
203	    }
204	
205	    /** 查询窗口当前可用容量。 */
206	    public CapacityResponse getCapacity(long windowId) {
207	        WindowRow window = repository.findWindowById(windowId);
208	        if (window == null) {
209	            throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + windowId);
210	        }
211	        CurtailmentRow active = repository.findActiveCurtailment(windowId);
212	        BigDecimal available = active != null ? active.volume() : window.plannedVolume();
213	        BigDecimal approved = repository.sumApprovedAmount(windowId);
214	        return new CapacityResponse(window.id(), fmt(window.plannedVolume()),
215	                active != null ? fmt(active.volume()) : null, fmt(available), fmt(approved),
216	                fmt(available.subtract(approved)));
217	    }
218	
219	    /** 查询窗口历史明细：窗口 + 全部申请 + 全部限供。 */
220	    public HistoryResponse getHistory(long windowId) {
221	        WindowRow window = repository.findWindowById(windowId);
222	        if (window == null) {
223	            throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + windowId);
224	        }
225	        CurtailmentRow active = repository.findActiveCurtailment(windowId);
226	        List<AllocationResponse> allocations = repository.listAllocations(windowId).stream()
227	                .map(this::toAllocationResponse).toList();
228	        List<CurtailmentResponse> curtailments = repository.listCurtailments(windowId).stream()
229	                .map(this::toCurtailmentResponse).toList();
230	        return new HistoryResponse(toWindowResponse(window, active), allocations, curtailments);
231	    }
232	
233	    // ------------------------------------------------------------------
234	    // 幂等命令框架
235	    // ------------------------------------------------------------------
236	
237	    /**
238	     * 在单事务内执行幂等命令：先占位插入命令行，再执行业务并写回响应。
239	     * 并发同键时占位插入会因唯一约束失败，随后读取已提交的首次结果重放或报 409。
240	     */
241	    private <T> T runCommand(String operation, String commandKey, String params, Class<T> type,
242	                             Supplier<T> business) {
243	        try {
244	            return tx.execute(status -> {
245	                CommandRow existing = repository.findCommand(commandKey);
246	                if (existing != null) {
247	                    return replay(existing, operation, params, type);
248	                }
249	                repository.insertCommand(commandKey, operation, params, nowNanos());
250	                T result = business.get();
251	                repository.updateCommandResponse(commandKey, toJson(result));
252	                return result;
253	            });
254	        } catch (DuplicateKeyException e) {
255	            CommandRow committed = repository.findCommand(commandKey);
256	            if (committed == null || committed.response() == null) {
257	                throw ApiException.conflict("COMMAND_CONFLICT", "相同 commandKey 的命令正在处理，请重试");
258	            }
259	            return replay(committed, operation, params, type);
260	        }
261	    }
262	
263	    private <T> T replay(CommandRow existing, String operation, String params, Class<T> type) {
264	        if (!existing.operation().equals(operation) || !existing.params().equals(params)) {
265	            throw ApiException.conflict("COMMAND_KEY_REUSED", "相同 commandKey 但参数不同，拒绝重放");
266	        }
267	        return fromJson(existing.response(), type);
268	    }
269	
270	    // ------------------------------------------------------------------
271	    // 内部工具
272	    // ------------------------------------------------------------------
273	
274	    private WindowRow lockWindowOf(AllocationRow allocation) {
275	        WindowRow window = repository.lockWindowById(allocation.windowId());
276	        if (window == null) {
277	            throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + allocation.windowId());
278	        }
279	        return window;
280	    }
281	
282	    private BigDecimal availableTotal(WindowRow window) {
283	        CurtailmentRow active = repository.findActiveCurtailment(window.id());
284	        return active != null ? active.volume() : window.plannedVolume();
285	    }
286	
287	    private WindowResponse toWindowResponse(WindowRow row, CurtailmentRow active) {
288	        BigDecimal available = active != null ? active.volume() : row.plannedVolume();
289	        return new WindowResponse(row.id(), row.windowKey(), row.channelId(), toIso(row.startNanos()),
290	                toIso(row.endNanos()), fmt(row.plannedVolume()),
291	                active != null ? fmt(active.volume()) : null, fmt(available), toIso(row.createdNanos()));
292	    }
293	
294	    private AllocationResponse toAllocationResponse(AllocationRow row) {
295	        return new AllocationResponse(row.allocationKey(), row.windowId(), row.userId(), fmt(row.amount()),
296	                row.requester(), row.status(), toIso(row.createdNanos()), toIso(row.updatedNanos()));
297	    }
298	
299	    private CurtailmentResponse toCurtailmentResponse(CurtailmentRow row) {
300	        return new CurtailmentResponse(row.id(), row.windowId(), fmt(row.volume()), row.status(),
301	                toIso(row.createdNanos()), row.cancelledNanos() == null ? null : toIso(row.cancelledNanos()));
302	    }
303	
304	    static long nowNanos() {
305	        return toNanos(Instant.now());
306	    }
307	
308	    /** Instant -> UTC 纳秒时间戳。 */
309	    static long toNanos(Instant instant) {
310	        return Math.addExact(Math.multiplyExact(instant.getEpochSecond(), NANOS_PER_SECOND), instant.getNano());
311	    }
312	
313	    /** UTC 纳秒时间戳 -> Instant。 */
314	    static Instant toInstant(long nanos) {
315	        return Instant.ofEpochSecond(Math.floorDiv(nanos, NANOS_PER_SECOND),
316	                Math.floorMod(nanos, NANOS_PER_SECOND));
317	    }
318	
319	    static String toIso(long nanos) {
320	        return toInstant(nanos).toString();
321	    }
322	
323	    static long parseInstant(String field, String value) {
324	        if (value == null || value.isBlank()) {
325	            throw ApiException.badRequest("INVALID_ARGUMENT", field + " 不能为空");
326	        }
327	        try {
328	            return toNanos(Instant.parse(value.trim()));
329	        } catch (DateTimeParseException | ArithmeticException e) {
330	            throw ApiException.badRequest("INVALID_ARGUMENT", field + " 不是合法的 UTC 时刻: " + value);
331	        }
332	    }
333	
334	    /** 解析水量：十进制字符串，大于 0，最多 3 位小数。 */
335	    static BigDecimal parseAmount(String field, String value) {
336	        if (value == null || value.isBlank()) {
337	            throw ApiException.badRequest("INVALID_ARGUMENT", field + " 不能为空");
338	        }
339	        String trimmed = value.trim();
340	        if (!AMOUNT_PATTERN.matcher(trimmed).matches()) {
341	            throw ApiException.badRequest("INVALID_ARGUMENT",
342	                    field + " 必须为大于 0 的十进制字符串，最多 3 位小数: " + value);
343	        }
344	        BigDecimal amount = new BigDecimal(trimmed);
345	        if (amount.signum() <= 0) {
346	            throw ApiException.badRequest("INVALID_ARGUMENT", field + " 必须大于 0");
347	        }
348	        return amount;
349	    }
350	
351	    static void requireKey(String field, String value) {
352	        if (value == null || !KEY_PATTERN.matcher(value).matches()) {
353	            throw ApiException.badRequest("INVALID_ARGUMENT",
354	                    field + " 不能为空，且仅允许字母数字及 . - _ :，最长 128 字符");
355	        }
356	    }
357	
358	    /** 水量格式化为十进制字符串（去掉多余尾零）。 */
359	    static String fmt(BigDecimal value) {
360	        BigDecimal stripped = value.stripTrailingZeros();
361	        if (stripped.signum() == 0) {
362	            return "0";
363	        }
364	        return stripped.toPlainString();
365	    }
366	
367	    private String toJson(Object value) {
368	        try {
369	            return objectMapper.writeValueAsString(value);
370	        } catch (Exception e) {
371	            throw new IllegalStateException("响应序列化失败", e);
372	        }
373	    }
374	
375	    private <T> T fromJson(String json, Class<T> type) {
376	        try {
377	            return objectMapper.readValue(json, type);
378	        } catch (Exception e) {
379	            throw new IllegalStateException("响应反序列化失败", e);
380	        }
381	    }
382	}
